function esc(s){return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
function cur(n){return "$"+Number(n||0).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2});}
function num(n){return Number(n||0).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2});}
var selUtil="ALL";
function render(){
  var m=appsmith.model||{}; var all=m.rows||[];
  var uset={}; all.forEach(function(r){ if(r.Utility) uset[r.Utility]=true; });
  var utils=Object.keys(uset).sort();
  if(selUtil!=="ALL" && utils.indexOf(selUtil)<0) selUtil="ALL";
  var rows=all.filter(function(r){ return selUtil==="ALL" || r.Utility===selUtil; });
  rows.sort(function(a,b){ return String(b._sort||"").localeCompare(String(a._sort||"")); });
  // group by Month, preserve order
  var order=[], groups={};
  rows.forEach(function(r){ var k=r.Month||"—"; if(!groups[k]){groups[k]=[];order.push(k);} groups[k].push(r); });

  var opts='<option value="ALL"'+(selUtil==="ALL"?" selected":"")+'>All Utilities</option>'
    + utils.map(function(u){ return '<option value="'+esc(u)+'"'+(selUtil===u?" selected":"")+'>'+esc(u)+'</option>'; }).join('');
  var html='<div class="filter"><label>Utility Type</label><select id="utilSel">'+opts+'</select></div>';

  if(m.isLoading){ html+='<div class="empty">Loading…</div>'; }
  else if(!order.length){ html+='<div class="empty">No bill history for this location</div>'; }
  else {
    order.forEach(function(mon){
      var g=groups[mon];
      var tot=g.reduce(function(s,r){ return s+Number(r.Cost||0); },0);
      html+='<div class="grp"><div class="ghead"><span class="gmonth">'+esc(mon)+'</span><span class="gtot">Total cost: '+cur(tot)+'</span></div>';
      html+='<table><thead><tr><th>Bill ID</th><th>Utility</th><th>Cost</th><th>Usage</th><th>Start Date</th><th>End Date</th><th>Days of Service</th><th>Details</th></tr></thead><tbody>';
      var totUse=0;
      g.forEach(function(r){
        var use=(r.Usage==null)?"-":(num(r.Usage)+(r.uom?(" "+r.uom):""));
        if(r.Usage!=null) totUse+=Number(r.Usage||0);
        html+='<tr><td class="link">'+esc(r["Bill ID"])+'</td><td>'+esc(r.Utility)+'</td><td>'+cur(r.Cost)+'</td><td>'+use+'</td><td>'+esc(r["Start Date"])+'</td><td>'+esc(r["End Date"])+'</td><td>'+esc(r["Days of Service"])+'</td><td class="link">More Details</td></tr>';
      });
      html+='<tr class="totrow"><td>Total:</td><td></td><td>'+cur(tot)+'</td><td>'+(totUse?num(totUse):"-")+'</td><td></td><td></td><td></td><td></td></tr>';
      html+='</tbody></table></div>';
    });
  }
  var root=document.getElementById("root"); if(!root) return;
  root.innerHTML='<div class="wrap">'+html+'</div>';
  var sel=document.getElementById("utilSel");
  if(sel) sel.onchange=function(e){ selUtil=e.target.value; render(); };
}
appsmith.onReady(function(){ render(); appsmith.onModelChange(render); });

